'use client'

import * as React from 'react'

import { cn } from '@/lib/utils'

export interface DataTableColumn<Row> {
  id: string
  header: string
  accessor?: keyof Row
  cell?: (row: Row, rowIndex: number) => React.ReactNode
  align?: 'left' | 'right' | 'center'
  width?: string
  sortable?: boolean
  financial?: boolean
}

export interface DataTableBaseProps<Row> {
  caption: string
  columns: DataTableColumn<Row>[]
  rows: Row[]
  getRowId: (row: Row, rowIndex: number) => string
  density?: 'dense' | 'standard'
  loading?: boolean
  error?: string
  emptyMessage?: string
  stickyHeader?: boolean
  initialSort?: { columnId: string; direction: 'asc' | 'desc' }
  onSort?: (columnId: string, direction: 'asc' | 'desc') => void
  onRowActivate?: (row: Row) => void
  onCellFocus?: (row: Row, columnId: string) => void
  className?: string
}

export function DataTableBase<Row>({
  caption,
  columns,
  rows,
  getRowId,
  density = 'dense',
  loading = false,
  error,
  emptyMessage = 'No records found',
  stickyHeader = true,
  initialSort,
  onSort,
  onRowActivate,
  onCellFocus,
  className
}: DataTableBaseProps<Row>) {
  const [sorting, setSorting] = React.useState(initialSort)
  const [focused, setFocused] = React.useState({ row: 0, column: 0 })
  const cellRefs = React.useRef(new Map<string, HTMLTableCellElement>())

  const sortedRows = React.useMemo(() => {
    if (!sorting) return rows
    const column = columns.find((candidate) => candidate.id === sorting.columnId)
    if (!column?.accessor) return rows
    const sorted = [...rows].sort((left, right) => {
      const leftValue = left[column.accessor!]
      const rightValue = right[column.accessor!]
      if (typeof leftValue === 'number' && typeof rightValue === 'number') return leftValue - rightValue
      if (leftValue === null || leftValue === undefined) return rightValue === null || rightValue === undefined ? 0 : -1
      if (rightValue === null || rightValue === undefined) return 1
      return String(leftValue).localeCompare(String(rightValue), undefined, { numeric: true })
    })
    return sorting.direction === 'asc' ? sorted : sorted.reverse()
  }, [columns, rows, sorting])

  const sort = (column: DataTableColumn<Row>) => {
    if (!column.sortable) return
    const direction = sorting?.columnId === column.id && sorting.direction === 'asc' ? 'desc' : 'asc'
    setSorting({ columnId: column.id, direction })
    onSort?.(column.id, direction)
  }

  const focusCell = (rowIndex: number, columnIndex: number) => {
    const row = Math.max(0, Math.min(sortedRows.length - 1, rowIndex))
    const column = Math.max(0, Math.min(columns.length - 1, columnIndex))
    setFocused({ row, column })
    window.requestAnimationFrame(() => cellRefs.current.get(`${row}:${column}`)?.focus())
  }

  if (error) {
    return (
      <div role="alert" className={cn('border border-financial-debit/35 bg-card p-3', className)}>
        <p className="text-[12px] font-semibold text-financial-debit">Unable to load {caption.toLowerCase()}</p>
        <p className="mt-1 text-[11px] text-muted-foreground">{error}</p>
      </div>
    )
  }

  return (
    <div role="region" aria-label={caption} tabIndex={0} className={cn('scrollbar-thin min-h-0 min-w-0 overflow-auto border bg-card outline-none focus-visible:ring-2 focus-visible:ring-ring', className)}>
      <table className="w-full min-w-max table-fixed border-collapse text-left text-[11px]">
        <caption className="sr-only">{caption}</caption>
        <colgroup>{columns.map((column) => <col key={column.id} style={column.width ? { width: column.width } : undefined} />)}</colgroup>
        <thead className={cn('z-10 bg-muted', stickyHeader && 'sticky top-0')}>
          <tr className={cn('border-b', density === 'dense' ? 'h-row-dense' : 'h-row-standard')}>
            {columns.map((column) => {
              const activeSort = sorting?.columnId === column.id
              return (
                <th key={column.id} scope="col" aria-sort={activeSort ? (sorting.direction === 'asc' ? 'ascending' : 'descending') : undefined} className={cn('border-r px-2 font-semibold last:border-r-0', column.align === 'right' && 'text-right', column.align === 'center' && 'text-center')}>
                  {column.sortable ? (
                    <button type="button" onClick={() => sort(column)} className={cn('inline-flex h-7 max-w-full items-center gap-1 text-[10px] uppercase tracking-[0.06em] text-muted-foreground hover:text-foreground focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-inset focus-visible:ring-ring', column.align === 'right' && 'ml-auto')}>
                      <span className="truncate">{column.header}</span>
                      <span aria-hidden className={cn('text-[8px]', !activeSort && 'opacity-25', activeSort && sorting.direction === 'asc' && 'rotate-180')}>▼</span>
                    </button>
                  ) : <span className="text-[10px] uppercase tracking-[0.06em] text-muted-foreground">{column.header}</span>}
                </th>
              )
            })}
          </tr>
        </thead>
        <tbody>
          {loading && Array.from({ length: 8 }, (_, rowIndex) => (
            <tr key={`loading-${rowIndex}`} className={cn('border-b', density === 'dense' ? 'h-row-dense' : 'h-row-standard')}>
              {columns.map((column, columnIndex) => <td key={column.id} className="border-r px-2 last:border-r-0"><span className={cn('block h-2 animate-pulse bg-muted', columnIndex % 2 ? 'w-3/4' : 'w-1/2')} /></td>)}
            </tr>
          ))}
          {!loading && sortedRows.map((row, rowIndex) => (
            <tr key={getRowId(row, rowIndex)} className={cn('border-b bg-card hover:bg-muted/45', density === 'dense' ? 'h-row-dense' : 'h-row-standard')}>
              {columns.map((column, columnIndex) => (
                <td
                  key={column.id}
                  ref={(node) => { if (node) cellRefs.current.set(`${rowIndex}:${columnIndex}`, node); else cellRefs.current.delete(`${rowIndex}:${columnIndex}`) }}
                  tabIndex={focused.row === rowIndex && focused.column === columnIndex ? 0 : -1}
                  onFocus={() => { setFocused({ row: rowIndex, column: columnIndex }); onCellFocus?.(row, column.id) }}
                  onDoubleClick={() => onRowActivate?.(row)}
                  onKeyDown={(event) => {
                    if (event.target !== event.currentTarget) return
                    if (event.key === 'ArrowDown') { event.preventDefault(); focusCell(rowIndex + 1, columnIndex) }
                    if (event.key === 'ArrowUp') { event.preventDefault(); focusCell(rowIndex - 1, columnIndex) }
                    if (event.key === 'ArrowRight') { event.preventDefault(); focusCell(rowIndex, columnIndex + 1) }
                    if (event.key === 'ArrowLeft') { event.preventDefault(); focusCell(rowIndex, columnIndex - 1) }
                    if (event.key === 'Enter') { event.preventDefault(); onRowActivate?.(row) }
                  }}
                  className={cn(
                    'overflow-hidden border-r px-2 outline-none last:border-r-0 focus-visible:relative focus-visible:z-[1] focus-visible:ring-1 focus-visible:ring-inset focus-visible:ring-financial-audit',
                    column.align === 'right' && 'text-right',
                    column.align === 'center' && 'text-center',
                    column.financial && 'financial-data'
                  )}
                >
                  <span className="block truncate">{column.cell ? column.cell(row, rowIndex) : column.accessor ? String(row[column.accessor]) : ''}</span>
                </td>
              ))}
            </tr>
          ))}
          {!loading && sortedRows.length === 0 && (
            <tr><td colSpan={columns.length} className="h-24 px-3 text-center text-[11px] text-muted-foreground">{emptyMessage}</td></tr>
          )}
        </tbody>
      </table>
    </div>
  )
}
